Outcome<LifeAgeBasisSnapshot> age_basis(const LifeAgeSources& src,const StableId& actor,const WorldMoment& at,const StableId& before,const WorldMoment& source_now,const CommonActualFactPrefix* prefix=nullptr){
    if(!src.common.actor(actor))return {false,{},common_failure("UnknownAgeActor",actor).error};
    if(const auto* original=src.foundation.actor_start_context.actor_age_bases.find(actor)){auto origin=read_authored_character_origin_v2(src.common.state(),src.foundation,src.foundation_catalog,actor);if(!origin.ok)return {false,{},origin.error};const auto* definition=src.foundation_catalog.actors.find(actor);if(!definition||original->actor_id!=actor||original->age_basis.kind!=AuthoredActorAgeBasis::Kind::declared_age_at_start||original->age_basis.years!=definition->age_basis.years||original->age_basis.as_of_tick!=definition->age_basis.as_of_tick||original->age_basis.calendar_year_ordinal!=definition->age_basis.calendar_year_ordinal||!actor_foundation_origin_equal(original->scenario_origin_ref,definition->scenario_origin_ref))return {false,{},common_failure("LifeAgeAuthoredBasisMismatch",actor).error};auto years=src.calendar.declared_age_at(original->age_basis.years,original->age_basis.as_of_tick,original->age_basis.calendar_year_ordinal,at);if(!years.ok)return {false,{},years.error};return {true,{DeclaredAgeBasisRef{DeclaredAgeBasisRef::Kind::actor_start,actor,actor},years.value},{}};}
    if(const auto* origin=src.foundation.character_origin_records.origins.find(actor);origin&&origin->origin_kind==CharacterOriginRecordV2::Kind::created){
        auto actual=read_created_character_origin_v2(src.common,src.foundation,src.foundation_catalog,src.control.catalog,src.control.shared,actor,source_now);if(!actual.ok)return {false,{},actual.error};
        auto valid=ordered_source(src.common,{"family","actor_creation",actor},before,prefix);if(!valid.ok)return {false,{},valid.error};
        const auto* age=std::get_if<DeclaredAgeAtRegistration>(&actual.value.registration->age_basis);if(!age||!equal(age->calendar_profile_ref,src.calendar.profile_ref()))return {false,{},common_failure("LifeAgeCreationCalendarMismatch",actor).error};
        auto years=src.calendar.declared_age_at(age->years,age->as_of_tick,age->calendar_year_ordinal,at);if(!years.ok)return {false,{},years.error};
        return {true,{DeclaredAgeBasisRef{DeclaredAgeBasisRef::Kind::creation_registration,actor,actual.value.registration->registration_result_id},years.value},{}};
    }
    const CharacterCreationFact* creation=nullptr;StableId creation_id;for(const auto& row:src.family.facts.rows())if(const auto* fact=std::get_if<CharacterCreationFact>(&row.second);fact&&fact->actor_id==actor){if(creation)return {false,{},common_failure("AmbiguousLifeAgeCreationBasis",actor).error};creation=fact;creation_id=row.first;}
    if(creation){auto valid=ordered_source(src.common,{"family","family_character_creation",creation_id},before,prefix);if(!valid.ok)return {false,{},valid.error};valid=validate_character_creation_source_body(src.common,src.family,src.control.catalog,src.control.shared);if(!valid.ok)return {false,{},valid.error};auto ordinal=src.calendar.year_ordinal(creation->created_tick);if(!ordinal.ok)return {false,{},ordinal.error};auto years=src.calendar.declared_age_at(creation->draft.age_years,creation->created_tick,ordinal.value,at);if(!years.ok)return {false,{},years.error};return {true,{DeclaredAgeBasisRef{DeclaredAgeBasisRef::Kind::creation_registration,actor,creation_id},years.value},{}};}
    const FamilyBirthRecord* birth=nullptr;StableId birth_id;for(const auto& row:src.births.births.rows())if(row.second.actor_id==actor){if(birth)return {false,{},common_failure("AmbiguousLifeAgeBirthBasis",actor).error};birth=&row.second;birth_id=row.first;}
    if(birth){auto valid=ordered_source(src.common,{"family_birth","family_birth_recorded",birth_id},before,prefix);if(!valid.ok)return {false,{},valid.error};bool complete_birth=false;for(const auto& module:src.foundation_catalog.identity.module_versions)if(module.first=="family_birth")complete_birth=module.second=="4";if(complete_birth){if(!src.born_sources||!src.born_sources->bound_to(src.common))return {false,{},common_failure("LifeAgeBornOriginalReadRequired",actor,ErrorKind::unsupported_capability).error};auto original=src.born_sources->read_original_birth({birth_id});if(!original.ok)return {false,{},original.error};if(original.value.birth!=birth)return {false,{},common_failure("LifeAgeBornOriginalSourceMismatch",actor,ErrorKind::internal).error};}const auto* person=src.common.state().actors.find(actor);const auto* accepted=src.births.replies.find(birth->accepted_id);if(!accepted||accepted->decision!="accepted"||accepted->due_tick>birth->tick||!person->birth_tick||*person->birth_tick!=birth->tick||!person->created_tick||*person->created_tick!=birth->tick)return {false,{},common_failure("LifeAgeBirthBasisMismatch",actor).error};auto years=src.calendar.exact_birth_age_at(birth->tick,at);if(!years.ok)return {false,{},years.error};return {true,{BirthFactRef{birth_id},years.value},{}};}
    return {false,{},common_failure("LifeAgeBasisSourceRequired",actor,ErrorKind::unsupported_capability).error};
}
